1	#include "marker.h"
2	
3	#include "CustomWidgets/siunitedit.h"
4	#include "markermodel.h"
5	#include "unit.h"
6	#include "preferences.h"
7	#include "markergroup.h"
8	#include "Util/util.h"
9	
10	#include <QPainter>
11	#include <QHBoxLayout>
12	#include <QLabel>
13	#include <QSpinBox>
14	#include <QDebug>
15	#include <QMenu>
16	#include <QActionGroup>
17	#include <QApplication>
18	#include <QDateTime>
19	#include <QCheckBox>
20	
21	using namespace std;
22	
23	Marker::Marker(MarkerModel *model, int number, Marker *parent, QString descr)
24	    : editingFrequency(false),
25	      model(model),
26	      parentTrace(nullptr),
27	      position(1000000000),
28	      minPosition(0),
29	      maxPosition(0),
30	      restrictPosition(false),
31	      number(number),
32	      visible(true),
33	      data(0),
34	      type(Type::Manual),
35	      description(descr),
36	      contextmenu(nullptr),
37	      delta(nullptr),
38	      parent(parent),
39	      cutoffAmplitude(-3.0),
40	      peakThreshold(-40.0),
41	      offset(10000),
42	      formatTable(Format::dBAngle),
43	      group(nullptr)
44	{
45	    creationTimestamp = QDateTime::currentSecsSinceEpoch();
46	    connect(this, &Marker::traceChanged, this, &Marker::updateContextmenu);
47	    connect(this, &Marker::typeChanged, this, &Marker::updateContextmenu);
48	    updateContextmenu();
49	
50	    connect(&Preferences::getInstance(), &Preferences::updated, this, &Marker::updateSymbol);
51	}
52	
53	Marker::~Marker()
54	{
55	    if(parentTrace) {
56	        parentTrace->removeMarker(this);
57	    }
58	    deleteHelperMarkers();
59	    emit deleted(this);
60	}
61	
62	void Marker::assignTrace(Trace *t)
63	{
64	    bool firstAssignment = false;
65	    if(parentTrace) {
66	        // remove connection from previous parent trace
67	        parentTrace->removeMarker(this);
68	        disconnect(parentTrace, &Trace::deleted, this, nullptr);
69	    } else {
70	        firstAssignment = true;
71	    }
72	    parentTrace = t;
73	    if(!getSupportedTypes().count(type)) {
74	        // new trace does not support the current type
75	        setType(Type::Manual);
76	    } else {
77	        // helper markers might change depending on the trace, update type even when type not changed
78	        setType(type);
79	    }
80	
81	    connect(parentTrace, &Trace::deleted, this, &Marker::parentTraceDeleted);
82	    connect(parentTrace, &Trace::dataChanged, this, &Marker::traceDataChanged);
83	    connect(parentTrace, &Trace::colorChanged, this, &Marker::updateSymbol);
84	    connect(parentTrace, &Trace::typeChanged, this, &Marker::traceTypeChanged);
85	    connect(parentTrace, &Trace::typeChanged, this, &Marker::checkDeltaMarker);
86	    constrainPosition();
87	    updateSymbol();
88	    parentTrace->addMarker(this);
89	    for(auto m : helperMarkers) {
90	        m->assignTrace(t);
91	    }
92	
93	    if(firstAssignment) {
94	        // Marker was just created and this is the first assignment to a trace.
95	        // Use display format on graph from preferences
96	        auto& p = Preferences::getInstance();
97	        if(p.Marker.defaultBehavior.showDataOnGraphs) {
98	            auto applicable = applicableFormats();
99	            for(auto f : defaultActiveFormats()) {
100	                if(find(applicable.begin(), applicable.end(), f) == applicable.end()) {
101	                    // this format is not allowed for this marker
102	                    continue;
103	                }
104	                formatGraph.insert(f);
105	            }
106	        }
107	    }
108	    constrainFormat();
109	    update();
110	    emit traceChanged(this);
111	}
112	
113	Trace *Marker::trace()
114	{
115	    return parentTrace;
116	}
117	
118	QString Marker::formatToString(Marker::Format f)
119	{
120	    switch(f) {
121	    case Format::dB: return "dB";
122	    case Format::dBm: return "dBm";
123	    case Format::dBuV: return "dBuV";
124	    case Format::dBAngle: return "dB + angle";
125	    case Format::RealImag: return "real + imag";
126	    case Format::Impedance: return "Impedance";
127	    case Format::VSWR: return "VSWR";
128	    case Format::SeriesR: return "Resistance";
129	    case Format::Capacitance: return "Capacitance";
130	    case Format::Inductance: return "Inductance";
131	    case Format::QualityFactor: return "Quality Factor";
132	    case Format::GroupDelay: return "Group Delay";
133	    case Format::NumberOfPeaks: return "Number of peaks";
134	    case Format::TOI: return "Third order intercept";
135	    case Format::AvgTone: return "Average Tone Level";
136	    case Format::AvgModulationProduct: return "Average Modulation Product Level";
137	    case Format::Noise: return "Noise level";
138	    case Format::PhaseNoise: return "Phase noise";
139	    case Format::Cutoff: return "Cutoff frequency";
140	    case Format::CenterBandwidth: return "Center + Bandwidth";
141	    case Format::InsertionLoss: return "Insertion loss";
142	    case Format::P1dB: return "P1dB";
143	    case Format::Flatness: return "Flatness";
144	    case Format::maxDeltaNeg: return "Max. Delta Negative";
145	    case Format::maxDeltaPos: return "Max. Delta Positive";
146	    case Format::Last: return "";
147	    }
148	    return "";
149	}
150	
151	Marker::Format Marker::formatFromString(QString s)
152	{
153	    for(int i=0;i<(int) Format::Last;i++) {
154	        if(s.compare(formatToString((Format) i)) == 0) {
155	            return (Format) i;
156	        }
157	    }
158	    return Format::Last;
159	}
160	
161	std::vector<Marker::Format> Marker::formats()
162	{
163	    std::vector<Format> ret;
164	    for(int i=0;i<(int) Format::Last;i++) {
165	        ret.push_back((Format) i);
166	    }
167	    return ret;
168	}
169	
170	std::vector<Marker::Format> Marker::applicableFormats()
171	{
172	    std::vector<Format> ret;
173	    switch(getDomain()) {
174	    case Trace::DataType::Time:
175	        switch(type) {
176	        case Type::Manual:
177	        case Type::Delta:
178	            ret.push_back(Format::dB);
179	            ret.push_back(Format::RealImag);
180	            if(parentTrace) {
181	                // check if step response data is available
182	                auto step = parentTrace->sample(parentTrace->index(position), true).y.real();
183	                if(!isnan(step)) {
184	                    ret.push_back(Format::Impedance);
185	                }
186	            }
187	            break;
188	        default:
189	            break;
190	        }
191	        break;
192	    case Trace::DataType::TimeZeroSpan:
193	        switch(type) {
194	        case Type::Manual:
195	        case Type::Delta:
196	        case Type::Maximum:
197	        case Type::Minimum:
198	            if(Trace::isSAParameter(parentTrace->liveParameter())) {
199	                ret.push_back(Format::dBm);
200	                ret.push_back(Format::dBuV);
201	            } else {
202	                ret.push_back(Format::dB);
203	                ret.push_back(Format::dBAngle);
204	                ret.push_back(Format::RealImag);
205	            }
206	            if(parentTrace) {
207	                if(parentTrace->isReflection()) {
208	                    ret.push_back(Format::Impedance);
209	                    ret.push_back(Format::VSWR);
210	                    ret.push_back(Format::SeriesR);
211	                    ret.push_back(Format::Capacitance);
212	                    ret.push_back(Format::Inductance);
213	                    ret.push_back(Format::QualityFactor);
214	                }
215	                if(!isnan(parentTrace->getNoise(parentTrace->minX()))) {
216	                    ret.push_back(Format::Noise);
217	                }
218	            }
219	            break;
220	        case Type::PeakTable:
221	        case Type::NegativePeakTable:
222	            ret.push_back(Format::NumberOfPeaks);
223	            break;
224	        default:
225	            break;
226	        }
227	        break;
228	    case Trace::DataType::Frequency:
229	        switch(type) {
230	        case Type::Manual:
231	        case Type::Delta:
232	        case Type::Maximum:
233	        case Type::Minimum:
234	            if(Trace::isSAParameter(parentTrace->liveParameter())) {
235	                ret.push_back(Format::dBm);
236	                ret.push_back(Format::dBuV);
237	            } else {
238	                ret.push_back(Format::dB);
239	                ret.push_back(Format::dBAngle);
240	                ret.push_back(Format::RealImag);
241	                ret.push_back(Format::GroupDelay);
242	            }
243	            if(parentTrace) {
244	                if(parentTrace->isReflection()) {
245	                    ret.push_back(Format::Impedance);
246	                    ret.push_back(Format::VSWR);
247	                    ret.push_back(Format::SeriesR);
248	                    ret.push_back(Format::Capacitance);
249	                    ret.push_back(Format::Inductance);
250	                    ret.push_back(Format::QualityFactor);
251	                }
252	                if(!isnan(parentTrace->getNoise(parentTrace->minX()))) {
253	                    ret.push_back(Format::Noise);
254	                }
255	            }
256	            break;
257	        case Type::PeakTable:
258	        case Type::NegativePeakTable:
259	            ret.push_back(Format::NumberOfPeaks);
260	            break;
261	        case Type::Bandpass:
262	            ret.push_back(Format::CenterBandwidth);
263	            ret.push_back(Format::InsertionLoss);
264	            break;
265	        case Type::Lowpass:
266	        case Type::Highpass:
267	            ret.push_back(Format::Cutoff);
268	            ret.push_back(Format::InsertionLoss);
269	            break;
270	        case Type::PhaseNoise:
271	            ret.push_back(Format::PhaseNoise);
272	            ret.push_back(Format::dB);
273	            break;
274	        case Type::TOI:
275	            ret.push_back(Format::TOI);
276	            ret.push_back(Format::AvgTone);
277	            ret.push_back(Format::AvgModulationProduct);
278	            break;
279	        case Type::Flatness:
