403	        return "";
404	    }
405	    if(position < parentTrace->minX() || position > parentTrace->maxX()) {
406	        return "";
407	    }
408	
409	    if(f == Format::Last) {
410	        // format not explicitly specified, use setting for table
411	        f = formatTable;
412	    }
413	
414	    switch(getDomain()) {
415	    case Trace::DataType::Time:
416	        if(type != Type::Delta) {
417	            switch(f) {
418	            case Format::dB:
419	                return Unit::ToString(Util::SparamTodB(data), "dB", " ", 4);
420	            case Format::RealImag:
421	                return Unit::ToString(data.real(), "", " ", 5) + "+"+Unit::ToString(data.imag(), "", " ", 5)+"j";
422	            case Format::Impedance: {
423	                auto step = parentTrace->sample(parentTrace->index(position), true).y.real();
