428	            default:
429	                return "Invalid";
430	            }
431	        } else {
432	            if(!delta || delta->getDomain() != Trace::DataType::Time) {
433	                return "Invalid";
434	            }
435	            switch(f) {
436	            case Format::dB:
437	                return "Δ:"+Unit::ToString(Util::SparamTodB(data) - Util::SparamTodB(delta->data), "dB", " ", 4);
438	            case Format::RealImag:
439	                return "Δ:"+Unit::ToString(data.real() - delta->data.real(), "", " ", 5) + "+"+Unit::ToString(data.imag() - delta->data.real(), "", " ", 5)+"j";
440	            case Format::Impedance: {
441	                auto step = parentTrace->sample(parentTrace->index(position), true).y.real();
442	                auto stepDelta = delta->parentTrace->sample(delta->parentTrace->index(delta->position), true).y.real();
443	                auto impedance = Util::SparamToImpedance(step, trace()->getReferenceImpedance()).real();
444	                auto impedanceDelta = Util::SparamToImpedance(stepDelta, trace()->getReferenceImpedance()).real();
445	                return "Δ:"+Unit::ToString(impedance - impedanceDelta, "Ω", "m kM", 3);
446	            }
447	                break;
448	            default:
449	                return "Invalid";
450	            }
451	        }
452	        break;
453	    case Trace::DataType::Frequency:
454	    case Trace::DataType::Power:
455	    case Trace::DataType::TimeZeroSpan:
456	        switch(type) {
457	        case Type::PeakTable:
458	        case Type::NegativePeakTable:
459	            switch(f) {
460	            case Format::NumberOfPeaks: return "Found " + QString::number(helperMarkers.size()) + " peak" + (helperMarkers.size() == 1 ? "" : "s");
461	            default: return "Invalid";
462	            }
463	            break;
464	        case Type::Delta: {
465	            if(!delta) {
466	                return "Invalid delta marker";
467	            }
468	            switch(f) {
469	            case Format::dB: return "Δ:"+Unit::ToString(Util::SparamTodB(data) - Util::SparamTodB(delta->data), "dB", " ", 4);
470	            case Format::dBm: return "Δ:"+Unit::ToString(Util::SparamTodB(data) - Util::SparamTodB(delta->data), "dBm", " ", 4);
471	            case Format::dBuV:
472	                return "Δ:"+Unit::ToString(Util::dBmTodBuV(Util::SparamTodB(data)) - Util::dBmTodBuV(Util::SparamTodB(delta->data)), "dBuV", " ", 4);
473	            case Format::dBAngle: {
474	                QString ret = "Δ:"+Unit::ToString(Util::SparamTodB(data) - Util::SparamTodB(delta->data), "dB", " ", 4) + "/";
475	                auto phase = arg(data)*180/M_PI;
476	                auto deltaphase = arg(delta->data)*180/M_PI;
477	                auto phasediff = phase - deltaphase;
478	                if(phasediff >= 2*M_PI) {
479	                    phasediff -= 2*M_PI;
480	                } else if(phasediff <= -2*M_PI) {
481	                    phasediff += 2*M_PI;
482	                }
483	                ret += Unit::ToString(phasediff, "°", " ", 4);
484	                return ret;
485	            }
486	            case Format::RealImag: return "Δ:"+Unit::ToString(data.real() - delta->data.real(), "", " ", 5) + "+"+Unit::ToString(data.imag() - delta->data.imag(), "", " ", 5)+"j";
487	            case Format::Impedance: {
