810	void Marker::traceDataChanged(unsigned int begin, unsigned int end)
811	{
812	    Q_UNUSED(begin)
813	    Q_UNUSED(end)
814	    complex<double> newdata;
815	    if(!parentTrace || parentTrace->numSamples() == 0) {
816	        // no data, invalidate
817	        newdata = numeric_limits<complex<double>>::quiet_NaN();
818	    } else {
819	        if(position < parentTrace->minX() || position > parentTrace->maxX()) {
820	            // this normally should not happen because the position is constrained to the trace X range.
821	            // However, when loading a setup, the trace might have been just created and essentially empty
822	            newdata = numeric_limits<complex<double>>::quiet_NaN();
823	        } else {
824	            // some data of the parent trace changed, check if marker data also changed
825	            newdata = parentTrace->interpolatedSample(position).y;
826	        }
827	    }
828	    if (newdata != data) {
829	        data = newdata;
830	        update();
831	        emit rawDataChanged();
832	    }
833	}
