835	void Marker::updateSymbol()
836	{
837	    if(isDisplayedMarker() && parentTrace) {
838	        auto style = Preferences::getInstance().Marker.symbolStyle;
839	        switch(style) {
840	        case MarkerSymbolStyle::FilledNumberInside: {
841	            constexpr int width = 15, height = 15;
842	            symbol = QPixmap(width, height);
843	            symbol.fill(Qt::transparent);
844	            QPainter p(&symbol);
845	            p.setRenderHint(QPainter::Antialiasing);
846	            QPointF points[] = {QPointF(0,0),QPointF(width,0),QPointF(width/2,height)};
847	            auto traceColor = parentTrace->color();
848	            p.setPen(traceColor);
849	            p.setBrush(traceColor);
850	            p.drawConvexPolygon(points, 3);
851	            p.setPen(Util::getFontColorFromBackground(traceColor));
852	            p.drawText(QRectF(0,0,width, height * 2.0 / 3.0), Qt::AlignCenter, QString::number(number) + suffix);
853	        }
854	            break;
855	        case MarkerSymbolStyle::FilledNumberAbove: {
856	            constexpr int width = 15, height = 30;
857	            symbol = QPixmap(width, height);
858	            symbol.fill(Qt::transparent);
859	            QPainter p(&symbol);
860	            p.setRenderHint(QPainter::Antialiasing);
861	            QPointF points[] = {QPointF(0,height/2),QPointF(width,height/2),QPointF(width/2,height)};
862	            auto traceColor = parentTrace->color();
863	            p.setPen(traceColor);
864	            p.setBrush(traceColor);
865	            p.drawConvexPolygon(points, 3);
866	            p.drawText(QRectF(0,0,width, height * 0.45), Qt::AlignCenter, QString::number(number) + suffix);
867	        }
868	            break;
869	        case MarkerSymbolStyle::EmptyNumberAbove: {
870	            constexpr int width = 15, height = 30;
871	            symbol = QPixmap(width, height);
872	            symbol.fill(Qt::transparent);
873	            QPainter p(&symbol);
874	            p.setRenderHint(QPainter::Antialiasing);
875	            QPointF points[] = {QPointF(0,height/2),QPointF(width,height/2),QPointF(width/2,height)};
876	            auto traceColor = parentTrace->color();
877	            p.setPen(traceColor);
878	            p.drawConvexPolygon(points, 3);
879	            p.drawText(QRectF(0,0,width, height * 0.45), Qt::AlignCenter, QString::number(number) + suffix);
880	        }
881	            break;
882	        }
883	    } else {
884	        symbol = QPixmap(1,1);
885	    }
