910	void Marker::updateContextmenu()
911	{
912	    // check if the contextmenu or one of its submenus is currently open
913	    auto *activeWidget = QApplication::activePopupWidget();
914	    while (activeWidget) {
915	        if(activeWidget == &contextmenu) {
916	            // contextmenu currently open, do not update
