1526	            c->setCurrentIndex(c->count() - 1);
1527	        }
1528	    }
1529	    if(type == Type::Delta) {
1530	        // add additional spinbox to choose corresponding delta marker
1531	        auto w = new QWidget;
1532	        auto layout = new QHBoxLayout;
1533	        layout->addWidget(c);
1534	        c->setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);
1535	        layout->setContentsMargins(0,0,0,0);
1536	        layout->setSpacing(0);
1537	        layout->addWidget(new QLabel("to"));
1538	        auto deltaChooser = new QComboBox;
1539	        for(auto m : model->getMarkers()) {
1540	            if(canUseAsDelta(m)) {
1541	                deltaChooser->addItem(QString::number(m->getNumber()));
1542	            }
1543	        }
1544	        if(delta) {
1545	            deltaChooser->setCurrentText(QString::number(delta->number));
1546	        }
1547	        connect(deltaChooser, qOverload<int>(&QComboBox::currentIndexChanged), [=](int){
1548	           bool found = false;
1549	           for(auto m : model->getMarkers()) {
1550	                if(m->number == deltaChooser->currentText().toInt()) {
1551	                    assignDeltaMarker(m);
1552	                    found = true;
1553	                    break;
1554	                }
1555	           }
1556	           if(!found) {
1557	               assignDeltaMarker(nullptr);
1558	           }
1559	           update();
1560	        });
1561	        deltaChooser->setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);
1562	        layout->addWidget(deltaChooser);
1563	        w->setLayout(layout);
1564	        c->setObjectName("Type");
1565	        if(delegate){
1566	            connect(c, qOverload<int>(&QComboBox::currentIndexChanged), [=](int) {
1567	                emit delegate->commitData(w);
1568	            });
1569	        }
1570	        return w;
1571	    } else {
1572	        // no delta marker, simply return the combobox
1573	        connect(c, qOverload<int>(&QComboBox::currentIndexChanged), [=](int) {
1574	            emit delegate->commitData(c);
1575	        });
1576	        return c;
1577	    }
1578	}
