1728	void Marker::adjustSettings(double value)
1729	{
1730	    switch(getDomain()) {
1731	    case Trace::DataType::Time:
1732	        switch(type) {
1733	        case Type::Manual:
1734	        case Type::Delta: {
1735	            // check if entered position is time or distance
1736	            if(value > parentTrace->sample(parentTrace->size() - 1).x) {
1737	                // entered a distance, convert to time
1738	                setPosition(parentTrace->distanceToTime(value));
1739	            } else {
1740	                // entered a time, can set directly
1741	                setPosition(value);
1742	            }
1743	        }
1744	            break;
1745	        default:
1746	            break;
1747	        }
1748	        break;
1749	    case Trace::DataType::TimeZeroSpan:
1750	        switch(type) {
1751	        case Type::Manual:
1752	        case Type::Maximum:
1753	        case Type::Minimum:
1754	        case Type::Delta:
1755	            setPosition(value);
1756	            break;
1757	        default:
1758	            break;
1759	        }
1760	        break;
1761	    case Trace::DataType::Frequency:
1762	        switch(type) {
1763	        case Type::Manual:
1764	        case Type::Maximum:
1765	        case Type::Minimum:
1766	        case Type::Delta:
1767	            setPosition(value);
1768	            break;
1769	        case Type::Lowpass:
1770	        case Type::Highpass:
1771	        case Type::Bandpass:
1772	            if(value > 0.0) {
1773	                value = -value;
1774	            }
1775	            cutoffAmplitude = value;
1776	            break;
1777	        case Type::PeakTable:
1778	        case Type::NegativePeakTable:
1779	            peakThreshold = value;
1780	            break;
1781	        case Type::PhaseNoise:
1782	            offset = value;
1783	            break;
1784	        default:
1785	            break;
1786	        }
1787	        break;
1788	    case Trace::DataType::Power:
1789	        switch(type) {
1790	        case Type::Manual:
1791	        case Type::Maximum:
1792	        case Type::Minimum:
1793	        case Type::Delta:
1794	            setPosition(value);
1795	            break;
1796	        default:
1797	            break;
1798	        }
1799	        break;
1800	    case Trace::DataType::Invalid:
1801	        break;
1802	    }
1803	    update();
1804	}
