1826	void Marker::update()
1827	{
1828	    if(!parentTrace->size()) {
1829	        // empty trace, nothing to do
1830	        return;
1831	    }
1832	    lines.clear();
1833	    auto xmin = restrictPosition ? minPosition : numeric_limits<double>::lowest();
1834	    auto xmax = restrictPosition ? maxPosition : numeric_limits<double>::max();
1835	    switch(type) {
1836	    case Type::Manual:
1837	    case Type::Delta:
1838	        // nothing to do
1839	        break;
1840	    case Type::Maximum:
1841	        setPosition(parentTrace->findExtremum(true, xmin, xmax));
1842	        break;
1843	    case Type::Minimum:
1844	        setPosition(parentTrace->findExtremum(false, xmin, xmax));
1845	        break;
1846	    case Type::PeakTable:
1847	    case Type::NegativePeakTable: {
1848	        auto peaks = parentTrace->findPeakFrequencies(100, peakThreshold, 3.0, xmin, xmax, type == Type::NegativePeakTable);
1849	        for(unsigned int i=0;i<peaks.size();i++) {
1850	            if(helperMarkers.size() <= i) {
1851	                // needs to create a new helper marker
1852	                auto helper = new Marker(model, number, this);
1853	                helper->suffix = QChar('a' + i);
1854	                helper->assignTrace(parentTrace);
1855	                helper->updateContextmenu();
1856	                helper->setVisible(visible);
1857	                helperMarkers.push_back(helper);
1858	            }
1859	            // update the position of the helper marker
1860	            helperMarkers[i]->setPosition(peaks[i]);
1861	        }
1862	        if(helperMarkers.size() > peaks.size()) {
1863	            // need to remove some helper markers
1864	            emit beginRemoveHelperMarkers(this);
1865	            for(unsigned int i = peaks.size(); i< helperMarkers.size();i++) {
1866	                delete helperMarkers[i];
1867	            }
1868	            helperMarkers.resize(peaks.size());
1869	            emit endRemoveHelperMarkers(this);
1870	        }
1871	    }
1872	        break;
1873	    case Type::Lowpass:
1874	    case Type::Highpass:
1875	        if(parentTrace->isReflection()) {
1876	            // lowpass/highpass calculation only works with transmission measurement
1877	            break;
1878	        } else {
1879	            // find the maximum
1880	            auto peakFreq = parentTrace->findExtremum(true, xmin, xmax);
1881	            // this marker shows the insertion loss
1882	            setPosition(peakFreq);
1883	            // find the cutoff frequency
1884	            auto index = parentTrace->index(peakFreq);
1885	            auto peakAmplitude = Util::SparamTodB(parentTrace->sample(index).y);
1886	            auto cutoff = peakAmplitude + cutoffAmplitude;
1887	            int inc = type == Type::Lowpass ? 1 : -1;
1888	            while(index >= 0 && index < (int) parentTrace->size()) {
1889	                auto sample = parentTrace->sample(index);
1890	                if(sample.x > xmax) {
1891	                    break;
1892	                }
1893	                auto amplitude = Util::SparamTodB(sample.y);
1894	                if(amplitude <= cutoff) {
1895	                    break;
1896	                }
1897	                index += inc;
1898	            }
1899	            if(index < 0) {
1900	                index = 0;
1901	            } else if(index >= (int) parentTrace->size()) {
1902	                index = parentTrace->size() - 1;
1903	            }
1904	            // set position of cutoff marker
1905	            helperMarkers[0]->setPosition(parentTrace->sample(index).x);
1906	        }
1907	        break;
1908	    case Type::Bandpass:
1909	        if(parentTrace->isReflection()) {
1910	            // lowpass/highpass calculation only works with transmission measurement
1911	            break;
1912	        } else {
1913	            // find the maximum
1914	            auto peakFreq = parentTrace->findExtremum(true);
1915	            // this marker shows the insertion loss
1916	            setPosition(peakFreq);
1917	            // find the cutoff frequencies
1918	            auto index = parentTrace->index(peakFreq);
1919	            auto peakAmplitude = Util::SparamTodB(parentTrace->sample(index).y);
1920	            auto cutoff = peakAmplitude + cutoffAmplitude;
1921	
1922	            auto low_index = index;
1923	            while(low_index >= 0) {
1924	                auto sample = parentTrace->sample(low_index);
1925	                if(sample.x < xmin) {
1926	                    break;
1927	                }
1928	                auto amplitude = Util::SparamTodB(sample.y);
1929	                if(amplitude <= cutoff) {
1930	                    break;
1931	                }
1932	                low_index--;
1933	            }
1934	            if(low_index < 0) {
1935	                low_index = 0;
1936	            }
1937	            // set position of cutoff marker
1938	            helperMarkers[0]->setPosition(parentTrace->sample(low_index).x);
1939	
1940	            auto high_index = index;
1941	            while(high_index < (int) parentTrace->size()) {
1942	                auto sample = parentTrace->sample(high_index);
1943	                if(sample.x > xmax) {
1944	                    break;
1945	                }
1946	                auto amplitude = Util::SparamTodB(sample.y);
1947	                if(amplitude <= cutoff) {
1948	                    break;
1949	                }
1950	                high_index++;
1951	            }
1952	            if(high_index >= (int) parentTrace->size()) {
1953	                high_index = parentTrace->size() - 1;
1954	            }
1955	            // set position of cutoff marker
1956	            helperMarkers[1]->setPosition(parentTrace->sample(high_index).x);
1957	            // set center marker inbetween cutoff markers
1958	            helperMarkers[2]->setPosition((helperMarkers[0]->position + helperMarkers[1]->position) / 2);
1959	        }
1960	        break;
1961	    case Type::TOI: {
1962	        auto peaks = parentTrace->findPeakFrequencies(2, -100, 3.0, xmin, xmax);
1963	        if(peaks.size() != 2) {
1964	            // error finding peaks, do nothing
1965	            break;
1966	        }
1967	        // assign marker frequenies:
1968	        // this marker is the left peak, first helper the right peak.
1969	        // 2nd and 3rd helpers are left and right TOI peaks
1970	        helperMarkers[0]->setPosition(peaks[0]);
1971	        helperMarkers[1]->setPosition(peaks[1]);
1972	        auto freqDiff = peaks[1] - peaks[0];
1973	        helperMarkers[2]->setPosition(peaks[0] - freqDiff);
1974	        helperMarkers[3]->setPosition(peaks[1] + freqDiff);
1975	    }
1976	        break;
1977	    case Type::PhaseNoise:
1978	        setPosition(parentTrace->findExtremum(true));
1979	        helperMarkers[0]->setPosition(position + offset);
1980	        break;
1981	    case Type::P1dB: {
1982	        // find maximum
1983	        auto maxpos = parentTrace->findExtremum(true, xmin, xmax);
1984	        // starting at the maximum point, traverse trace data towards higher power levels until amplitude dropped by 1dB
1985	        auto maxindex = parentTrace->index(maxpos);
1986	        auto maxpower = abs(parentTrace->sample(maxindex).y);
1987	        double p1db = parentTrace->maxX() > xmax ? xmax : parentTrace->maxX();
1988	        for(unsigned int i = maxindex; i < parentTrace->size(); i++) {
1989	            auto sample = parentTrace->sample(i);
1990	            if(sample.x > xmax) {
1991	                break;
1992	            }
1993	            if(Util::SparamTodB(maxpower) - Util::SparamTodB(sample.y) >= 1.0) {
1994	                p1db = sample.x;
1995	                break;
1996	            }
1997	        }
1998	        setPosition(p1db);
1999	    }
2000	        break;
2001	    case Type::Flatness: {
2002	        auto lower = helperMarkers[0]->getData();
2003	        auto upper = helperMarkers[1]->getData();
2004	        auto posLower = helperMarkers[0]->getPosition();
2005	        auto posUpper = helperMarkers[1]->getPosition();
2006	        // three additional lines:
2007	        // 0: line between lower and upper markers
2008	        // 1: positive peak deviation
2009	        // 2: negative peak deviation
2010	        lines.resize(3);
2011	        lines[0].p1.x = posLower;
2012	        lines[0].p1.y = lower;
2013	        lines[0].p2.x = posUpper;
2014	        lines[0].p2.y = upper;
2015	        if(posLower > posUpper) {
2016	            swap(posLower, posUpper);
2017	            swap(lower, upper);
2018	        }
2019	        auto startIndex = parentTrace->index(posLower);
2020	        auto stopIndex = parentTrace->index(posUpper);
2021	        maxDeltaNeg = std::numeric_limits<double>::lowest();
2022	        maxDeltaPos = std::numeric_limits<double>::lowest();
2023	        for(int i=startIndex;i<=stopIndex;i++) {
2024	            auto sample = parentTrace->sample(i);
2025	            auto dbTrace = Util::SparamTodB(sample.y);
2026	            auto dbStraightLine = Util::Scale((double) i, (double) startIndex, (double) stopIndex, Util::SparamTodB(lower), Util::SparamTodB(upper));
2027	            auto straightLine = Util::dBToMagnitude(dbStraightLine);
2028	            auto delta = dbTrace - dbStraightLine;
2029	            if(delta > maxDeltaPos) {
2030	                maxDeltaPos = delta;
2031	                lines[1].p1.x = sample.x;
2032	                lines[1].p1.y = sample.y;
2033	                lines[1].p2.x = sample.x;
2034	                lines[1].p2.y = straightLine;
2035	            }
2036	            if(-delta > maxDeltaNeg) {
2037	                maxDeltaNeg = -delta;
2038	                lines[2].p1.x = sample.x;
2039	                lines[2].p1.y = sample.y;
2040	                lines[2].p2.x = sample.x;
2041	                lines[2].p2.y = straightLine;
2042	            }
2043	        }
2044	    }
2045	        break;
2046	    case Type::Last:
2047	        break;
2048	    }
2049	    emit dataChanged(this);
2050	}
